import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { readFileSync } from "node:fs";
const tok = JSON.parse(readFileSync("<scratch>", "utf8")).token;
const [, , tool, argsJson] = process.argv;
const args = argsJson ? JSON.parse(argsJson) : {};
const t0 = Date.now();
const client = new Client({ name: "done8-maria", version: "1.0.0" });
const transport = new StreamableHTTPClientTransport(new URL("http://localhost:8810/mcp"), {
  requestInit: { headers: { Authorization: `Bearer ${tok}` } },
});
try {
  await client.connect(transport);
  const r = await client.callTool({ name: tool, arguments: args });
  const text = (r.content || []).map(c => c.text ?? JSON.stringify(c)).join("\n");
  console.log(`[${tool}] ${Date.now() - t0}ms isError=${!!r.isError}`);
  console.log(text);
} catch (e) {
  console.log(`[${tool}] MCP ERROR after ${Date.now() - t0}ms: ${e.message}`);
  process.exitCode = 1;
} finally {
  await client.close().catch(() => {});
}
EOF
